const plant=new T.Group();scene.add(plant);plant.position.set(-4,.01,-.8);mesh(plant,new T.CylinderGeometry(.38,.28,.65,32),material(0xba9077,.9),0,.31,0);for(let i=0;i<7;i++){const angle=i*2.399,y=.9+i*.13,x=Math.cos(angle)*.27,z=Math.sin(angle)*.27;rod(plant,V(0,.6,0),V(x,y,z),.018,material(0x778b64));const leaf=ball(plant,i%2?0x8b9d76:0xa0ad85,x,y,z,.18,.38,.055);leaf.rotation.set(.3,angle,-.5+x);}
